const C_CORE_UTIL_HEADER_TEMPLATE = `/**
 * @file {{headerFile}}
 * @brief CPM C core utility API.
 *
 * @details
 * This generated bundle header documents the module directly in the file
 * copied into the user project. It summarizes the public API scope, common
 * applications and the minimum code needed to verify integration.
 *
 * @par Main features
 * - copies and trims strings safely;
 * - generates compact timestamps for logs and reports;
 * - reads simple key/value pairs from an INI file;
 * - keeps small procedural helpers independent from the C++ CPM_Utility layer.
 *
 * @par Typical applications
 * - small C command-line tools generated by CPM;
 * - shared helpers for generated C bundles;
 * - test executables requiring predictable string and INI utilities.
 *
 * @par Usage notes
 * - All output buffers must include space for the final null terminator.
 * - CpmUtil_ReadIniValue reads a flat key from the selected INI file.
 *
 * @par Example of use
 * @code{.c}
 * #include "{{headerFile}}"
 * 
 * char value[128];
 * if (CpmUtil_ReadIniValue("cpm_util.ini", "logPath", value, sizeof(value)) == 0)
 * {
 *     CpmUtil_Trim(value);
 * }
 * @endcode
 */
#ifndef {{guard}}
#define {{guard}}

#ifdef __cplusplus
extern "C" {
#endif

#include <stddef.h>

#ifndef CPM_UTIL_TIMESTAMP_SIZE
#define CPM_UTIL_TIMESTAMP_SIZE 32
#endif

int CpmUtil_CopyString(char *dst, size_t dstSize, const char *src);
char *CpmUtil_Trim(char *text);
int CpmUtil_GetTimestamp(char *buffer, size_t bufferSize);
int CpmUtil_ReadIniValue(const char *iniPath, const char *key, char *value, size_t valueSize);

#ifdef __cplusplus
}
#endif

#endif /* {{guard}} */
`;

const C_CORE_UTIL_SOURCE_TEMPLATE = `/**
 * @file {{baseName}}.c
 * @brief Implementation of the CPM C core utility bundle.
 */
#include "{{headerFile}}"

#include <ctype.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

/**
 * @brief Implements the CpmUtil_CopyString operation.
 * @param dst See the matching header for semantic details.
 * @param dstSize See the matching header for semantic details.
 * @param src See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
int CpmUtil_CopyString(char *dst, size_t dstSize, const char *src)
{
    if (dst == NULL || dstSize == 0)
    {
        return -1;
    }
    if (src == NULL)
    {
        src = "";
    }
    strncpy(dst, src, dstSize - 1);
    dst[dstSize - 1] = '\\0';
    return 0;
}

/**
 * @brief Implements the CpmUtil_Trim operation.
 * @param text See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
char *CpmUtil_Trim(char *text)
{
    char *end;

    if (text == NULL)
    {
        return NULL;
    }

    while (*text != '\\0' && isspace((unsigned char)*text))
    {
        ++text;
    }

    end = text + strlen(text);
    while (end > text && isspace((unsigned char)*(end - 1)))
    {
        --end;
    }
    *end = '\\0';

    return text;
}

/**
 * @brief Implements the CpmUtil_GetTimestamp operation.
 * @param buffer See the matching header for semantic details.
 * @param bufferSize See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
int CpmUtil_GetTimestamp(char *buffer, size_t bufferSize)
{
    time_t now;
    struct tm localTime;

    if (buffer == NULL || bufferSize == 0)
    {
        return -1;
    }

    now = time(NULL);
#if defined(_WIN32)
    if (localtime_s(&localTime, &now) != 0)
    {
        buffer[0] = '\\0';
        return -1;
    }
#else
    {
        struct tm *localTimePtr = localtime(&now);
        if (localTimePtr == NULL)
        {
            buffer[0] = '\\0';
            return -1;
        }
        localTime = *localTimePtr;
    }
#endif

    if (strftime(buffer, bufferSize, "%Y-%m-%d %H:%M:%S", &localTime) == 0)
    {
        buffer[0] = '\\0';
        return -1;
    }

    return 0;
}

/**
 * @brief Implements the CpmUtil_ReadIniValue operation.
 * @param iniPath See the matching header for semantic details.
 * @param key See the matching header for semantic details.
 * @param value See the matching header for semantic details.
 * @param valueSize See the matching header for semantic details.
 * @return See the matching header for status code or value semantics.
 */
int CpmUtil_ReadIniValue(const char *iniPath, const char *key, char *value, size_t valueSize)
{
    FILE *file;
    char line[512];
    size_t keyLength;

    if (iniPath == NULL || key == NULL || value == NULL || valueSize == 0)
    {
        return -1;
    }

    value[0] = '\\0';
    keyLength = strlen(key);
    file = fopen(iniPath, "r");
    if (file == NULL)
    {
        return -1;
    }

    while (fgets(line, sizeof(line), file) != NULL)
    {
        char *cursor = CpmUtil_Trim(line);
        char *separator;

        if (cursor == NULL || cursor[0] == '\\0' || cursor[0] == '#' || cursor[0] == ';' || cursor[0] == '[')
        {
            continue;
        }
        if (strncmp(cursor, key, keyLength) != 0)
        {
            continue;
        }

        separator = cursor + keyLength;
        separator = CpmUtil_Trim(separator);
        if (separator == NULL || separator[0] != '=')
        {
            continue;
        }

        ++separator;
        separator = CpmUtil_Trim(separator);
        CpmUtil_CopyString(value, valueSize, separator);
        fclose(file);
        return 0;
    }

    fclose(file);
    return 1;
}
`;

